// AdminDashboard.js
// Clean, professional UI with functional boxes (NO functionality changed!)
// You can plug your existing fetch functions into the placeholders.

import React, { useEffect, useState } from 'react';
import './AdminDashboard.css';

export default function AdminDashboard({ fetchNGOs, fetchEvents, fetchVolunteers, fetchTopNGO, fetchTopVolunteer, fetchDonations, deleteNGO, deleteEvent, deleteVolunteer }) {
  const [ngos, setNgos] = useState([]);
  const [events, setEvents] = useState([]);
  const [volunteers, setVolunteers] = useState([]);
  const [topNGO, setTopNGO] = useState(null);
  const [topVolunteer, setTopVolunteer] = useState(null);
  const [donations, setDonations] = useState(0);

  useEffect(() => {
    fetchNGOs().then(setNgos);
    fetchEvents().then(setEvents);
    fetchVolunteers().then(setVolunteers);
    fetchTopNGO().then(setTopNGO);
    fetchTopVolunteer().then(setTopVolunteer);
    fetchDonations().then(setDonations);
  }, []);

  return (
    <div className="admin-dashboard-container">

      {/* TOTAL NGOs */}
      <div className="dashboard-box">
        <div className="box-icon">🏢</div>
        <h3>Total NGOs</h3>
        <p className="count-number">{ngos.length}</p>
        <div className="scroll-area">
          {ngos.map((n) => (
            <div key={n.id} className="scroll-item">
              <span>{n.name}</span>
              <button className="delete-btn" onClick={() => deleteNGO(n.id)}>Delete</button>
            </div>
          ))}
        </div>
      </div>

      {/* TOTAL EVENTS */}
      <div className="dashboard-box">
        <div className="box-icon">📅</div>
        <h3>Total Events</h3>
        <p className="count-number">{events.length}</p>
        <div className="scroll-area">
          {events.map((e) => (
            <div key={e.id} className="scroll-item">
              <span>{e.title}</span>
              <button className="delete-btn" onClick={() => deleteEvent(e.id)}>Delete</button>
            </div>
          ))}
        </div>
      </div>

      {/* TOTAL VOLUNTEERS */}
      <div className="dashboard-box">
        <div className="box-icon">🙋</div>
        <h3>Total Volunteers</h3>
        <p className="count-number">{volunteers.length}</p>
        <div className="scroll-area">
          {volunteers.map((v) => (
            <div key={v.id} className="scroll-item">
              <span>{v.name}</span>
              <button className="delete-btn" onClick={() => deleteVolunteer(v.id)}>Delete</button>
            </div>
          ))}
        </div>
      </div>

      {/* TOP PERFORMING NGO */}
      <div className="dashboard-box highlight-box">
        <div className="box-icon">🥇</div>
        <h3>Top Performing NGO</h3>
        {topNGO ? (
          <div className="badge-box">{topNGO.name}</div>
        ) : (
          <p>No data available</p>
        )}
      </div>

      {/* TOP PERFORMING VOLUNTEER */}
      <div className="dashboard-box highlight-box">
        <div className="box-icon">🏅</div>
        <h3>Top Performing Volunteer</h3>
        {topVolunteer ? (
          <div className="badge-box">{topVolunteer.name}</div>
        ) : (
          <p>No data available</p>
        )}
      </div>

      {/* DONATIONS OVERVIEW */}
      <div className="dashboard-box">
        <div className="box-icon">💰</div>
        <h3>Total Donations</h3>
        <p className="count-number">₹{donations}</p>
      </div>

    </div>
  );
}
